package com.edgecloud.alert.service;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant; import java.util.HexFormat; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.edgecloud.alert.entity.*; import com.edgecloud.alert.evaluation.AlertEvaluationResult; import com.edgecloud.alert.repository.*;
@Service public class AlertSuppressionService {private final MaintenanceWindowRepository windows;private final AlertSuppressionHistoryRepository history;public AlertSuppressionService(MaintenanceWindowRepository w,AlertSuppressionHistoryRepository h){windows=w;history=h;}
 @Transactional public int suppressMatching(AlertEvaluationResult result){if(!result.triggered())return 0;AlertEventSourceType sourceType=AlertEventSourceType.valueOf(result.sourceType().name());Instant at=result.evaluatedAt();int count=0;for(MaintenanceWindow window:windows.findActive(result.projectId(),at)){if(!window.matches(sourceType,result.sourceId().trim()))continue;String key=dedup(window,result);if(history.existsByMaintenanceWindowIdAndDedupKey(window.getId(),key))continue;history.save(new AlertSuppressionHistory(result.projectId(),window.getId(),result.ruleId(),result.ruleName().trim(),sourceType,result.sourceId().trim(),result.metricType(),result.observedValue(),result.threshold(),at,Instant.now(),window.getName(),window.getReason(),key));count++;}return count;}
 private String dedup(MaintenanceWindow window,AlertEvaluationResult r){String value=window.getId()+"|"+r.ruleId()+"|"+r.sourceType()+"|"+r.sourceId().trim()+"|"+r.metricType()+"|"+r.evaluatedAt();try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException ex){throw new IllegalStateException("SHA-256 unavailable",ex);}}
}
